@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=${FLORES_TEST_DB_URL:jdbc:postgresql://127.0.0.1:5432/flores_test}","spring.datasource.username=${FLORES_TEST_DB_USER:flores}","spring.datasource.password=${FLORES_TEST_DB_PASSWORD:}","flores.seed=true"})
class SistemaIntegrationTest {
 @Autowired SqlDao db;@Autowired VentaService sales;@Autowired EmbarqueService boarding;@Autowired FidelizacionService points;@Autowired CatalogoService catalogs;@Autowired ManifiestoService manifests;@Autowired ReportesService reports;@Autowired PasswordEncoder encoder;
 @LocalServerPort int port;
 static AtomicInteger seq=new AtomicInteger((int)(System.currentTimeMillis()%10000000));
 long trip,seat,passenger;String document;
 void auth(String user,String role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user,"",List.of(new SimpleGrantedAuthority("ROLE_"+role))));}
 @BeforeEach void setup(){auth("admin","ADMIN");int n=seq.incrementAndGet();LocalDate today=LocalDate.now(ZoneId.of("America/Lima"));long route=db.insert("INSERT INTO ruta(origen,destino,distancia_km,duracion_min) VALUES('Lima','Prueba',300,240)");long bus=db.insert("INSERT INTO bus(placa,marca,capacidad,soat_hasta,revision_hasta,estado) VALUES(?,'Prueba',4,?,?,'OPERATIVO')","T-"+n,today.plusYears(1),today.plusYears(1));long driver=db.insert("INSERT INTO conductor(nombres,apellidos,licencia,categoria,vencimiento) VALUES('Prueba','Test',?,'AIIIC',?)","LIC-"+n,today.plusYears(1));for(int i=1;i<=4;i++)db.update("INSERT INTO asiento(bus_id,numero,piso,tipo) VALUES(?,?,1,'CAMA')",bus,i);trip=db.insert("INSERT INTO viaje(ruta_id,bus_id,conductor_id,salida,precio,estado) VALUES(?,?,?,?,100,'PROGRAMADO')",route,bus,driver,today.plusDays(30).atTime(12,0));db.update("INSERT INTO reserva(viaje_id,asiento_id) SELECT ?,id FROM asiento WHERE bus_id=?",trip,bus);seat=db.count("SELECT MIN(id) FROM asiento WHERE bus_id=?",bus);document=String.valueOf(80000000+n);passenger=db.insert("INSERT INTO pasajero(tipo_documento,documento,nombres,apellidos) VALUES('DNI',?,'Prueba','Automatizada')",document);db.update("INSERT INTO cuenta_fidelizacion(pasajero_id,saldo) VALUES(?,500)",passenger);}
 @AfterEach void cleanup(){SecurityContextHolder.clearContext();}
 Venta cmd(long tripId,long seatId,long p,String token,int redeemed){return new Venta(tripId,seatId,p,token,null,redeemed,"EFECTIVO",null,"VENTANILLA",false);}
 ResultadoVenta sale(int redeemed){var r=sales.reserve(new Reserva(trip,seat));return sales.sell(cmd(trip,seat,passenger,r.get("token").toString(),redeemed));}
 @Test void salePersistsTicketPaymentAndSeat(){var t=sale(0);assertEquals(1,db.count("SELECT COUNT(*) FROM pago WHERE boleto_id=? AND estado='APROBADO'",t.id()));assertEquals(t.id(),db.count("SELECT boleto_id FROM reserva WHERE viaje_id=? AND asiento_id=?",trip,seat));assertEquals(new BigDecimal("100.00"),t.total());}
 @Test void sameSeatCannotBeReservedByAnotherUser(){sales.reserve(new Reserva(trip,seat));auth("vendedor","VENDEDOR");assertThrows(BusinessException.class,()->sales.reserve(new Reserva(trip,seat)));}
 @Test void expiredReservationCannotSell(){var r=sales.reserve(new Reserva(trip,seat));db.update("UPDATE reserva SET vence=? WHERE viaje_id=? AND asiento_id=?",LocalDateTime.now().minusDays(1),trip,seat);assertThrows(BusinessException.class,()->sales.sell(cmd(trip,seat,passenger,r.get("token").toString(),0)));assertEquals(0,db.count("SELECT COUNT(*) FROM boleto WHERE viaje_id=?",trip));}
 @Test void expiredReservationCanBeReplaced(){sales.reserve(new Reserva(trip,seat));db.update("UPDATE reserva SET vence=? WHERE viaje_id=?",LocalDateTime.now().minusDays(1),trip);auth("vendedor","VENDEDOR");assertNotNull(sales.reserve(new Reserva(trip,seat)).get("token"));}
 @Test void tokenOfAnotherOwnerIsRejected(){String token=sales.reserve(new Reserva(trip,seat)).get("token").toString();auth("vendedor","VENDEDOR");assertThrows(BusinessException.class,()->sales.sell(cmd(trip,seat,passenger,token,0)));}
 @Test void foreignSeatIsRejected(){long wrong=db.count("SELECT MAX(id) FROM asiento WHERE id<>? AND bus_id<>(SELECT bus_id FROM viaje WHERE id=?)",seat,trip);assertThrows(NoSuchElementException.class,()->sales.reserve(new Reserva(trip,wrong)));}
 @Test void rejectedPaymentCreatesNoPartialRecords(){var r=sales.reserve(new Reserva(trip,seat));assertThrows(BusinessException.class,()->sales.sell(new Venta(trip,seat,passenger,r.get("token").toString(),null,0,"TARJETA","TEST-REJECT","WEB",true)));assertEquals(0,db.count("SELECT COUNT(*) FROM boleto WHERE viaje_id=?",trip));assertEquals(500,db.count("SELECT saldo FROM cuenta_fidelizacion WHERE pasajero_id=?",passenger));}
 @Test void digitalPaymentRequiresOperation(){var r=sales.reserve(new Reserva(trip,seat));assertThrows(BusinessException.class,()->sales.sell(new Venta(trip,seat,passenger,r.get("token").toString(),null,0,"YAPE","","WEB",false)));}
 @Test void promotionAndPointsAreCalculatedOnServer(){var q=sales.quote(trip,passenger,"FLORES10",100);assertEquals(new BigDecimal("80.00"),q.get("total"));}
 @Test void expiredPromotionIsRejected(){db.update("INSERT INTO promocion(nombre,codigo,tipo,valor,desde,hasta) VALUES('Vieja',?,'PORCENTAJE',10,?,?)","OLD"+trip,LocalDate.now().minusDays(10),LocalDate.now().minusDays(2));assertThrows(BusinessException.class,()->sales.quote(trip,passenger,"OLD"+trip,0));}
 @Test void insufficientPointsAreRejected(){assertThrows(BusinessException.class,()->sales.quote(trip,passenger,null,501));}
 @Test void redemptionCannotExceedFare(){db.update("UPDATE cuenta_fidelizacion SET saldo=2000 WHERE pasajero_id=?",passenger);assertThrows(BusinessException.class,()->sales.quote(trip,passenger,null,1001));}
 @Test void boardingAwardsPointsOnlyOnce(){var t=sale(100);var r=boarding.board(trip,new Embarque(t.qr(),document));assertEquals(30,r.get("puntos"));assertThrows(BusinessException.class,()->boarding.board(trip,new Embarque(t.qr(),document)));assertEquals(430,db.count("SELECT saldo FROM cuenta_fidelizacion WHERE pasajero_id=?",passenger));assertEquals(1,db.count("SELECT COUNT(*) FROM movimiento_puntos WHERE boleto_id=? AND tipo='ACUMULA'",t.id()));}
 @Test void wrongDocumentCannotBoard(){var t=sale(0);assertThrows(BusinessException.class,()->boarding.board(trip,new Embarque(t.qr(),"11111111")));assertEquals("EMITIDO",sales.ticket(t.id()).get("estado"));}
 @Test void wrongTripCannotBoard(){var t=sale(0);long other=db.count("SELECT MIN(id) FROM viaje WHERE id<>?",trip);assertThrows(BusinessException.class,()->boarding.board(other,new Embarque(t.qr(),document)));}
 @Test void cancelReturnsPointsAndFreesSeat(){var t=sale(100);sales.cancel(t.id());assertEquals(500,db.count("SELECT saldo FROM cuenta_fidelizacion WHERE pasajero_id=?",passenger));assertEquals("REEMBOLSADO",db.one("SELECT estado FROM pago WHERE boleto_id=?",t.id()).get("estado"));assertNotNull(sales.reserve(new Reserva(trip,seat)).get("token"));assertThrows(BusinessException.class,()->sales.cancel(t.id()));}
 @Test void utilizedTicketCannotBeCancelled(){var t=sale(0);boarding.board(trip,new Embarque(t.qr(),document));assertThrows(BusinessException.class,()->sales.cancel(t.id()));}
 @Test void closedManifestCannotReceiveBoarding(){var t=sale(0);var r=sales.reserve(new Reserva(trip,seat+1));var second=sales.sell(cmd(trip,seat+1,passenger,r.get("token").toString(),0));boarding.board(trip,new Embarque(t.qr(),document));manifests.send(trip,false);assertThrows(BusinessException.class,()->boarding.board(trip,new Embarque(second.qr(),document)));assertThrows(BusinessException.class,()->sales.reserve(new Reserva(trip,seat+2)));}
 @Test void manifestRetryIsIdempotent(){var t=sale(0);boarding.board(trip,new Embarque(t.qr(),document));manifests.send(trip,true);assertEquals("ERROR",db.one("SELECT estado_envio FROM manifiesto WHERE viaje_id=?",trip).get("estado_envio"));manifests.send(trip,false);manifests.send(trip,false);assertEquals(2,db.count("SELECT intentos FROM manifiesto WHERE viaje_id=?",trip));assertEquals(1,db.count("SELECT total_pasajeros FROM manifiesto WHERE viaje_id=?",trip));}
 @Test void emptyManifestCannotBeSent(){assertThrows(BusinessException.class,()->manifests.send(trip,false));}
 @Test void rescheduleCommitsOldAndNewTogether(){var old=sale(0);var r=sales.reserve(new Reserva(trip,seat+1));sales.reprogram(old.id(),new Reprogramacion(trip,seat+1,r.get("token").toString(),"EFECTIVO",null));assertEquals("ANULADO",sales.ticket(old.id()).get("estado"));assertEquals(1,db.count("SELECT COUNT(*) FROM boleto WHERE reprogramado_desde=? AND estado='EMITIDO'",old.id()));}
 @Test void failedRescheduleKeepsOriginalTicket(){var old=sale(0);var r=sales.reserve(new Reserva(trip,seat+1));assertThrows(BusinessException.class,()->sales.reprogram(old.id(),new Reprogramacion(trip,seat+1,r.get("token").toString(),"INVALID",null)));assertEquals("EMITIDO",sales.ticket(old.id()).get("estado"));assertEquals("APROBADO",db.one("SELECT estado FROM pago WHERE boleto_id=?",old.id()).get("estado"));}
 @Test void competingSalesProduceOneTicket()throws Exception{String token=sales.reserve(new Reserva(trip,seat)).get("token").toString();var pool=Executors.newFixedThreadPool(2);try{var gate=new CountDownLatch(1);Callable<Boolean> attempt=()->{auth("admin","ADMIN");gate.await();try{sales.sell(cmd(trip,seat,passenger,token,0));return true;}catch(BusinessException e){return false;}finally{SecurityContextHolder.clearContext();}};var a=pool.submit(attempt);var b=pool.submit(attempt);gate.countDown();assertEquals(1,(a.get()?1:0)+(b.get()?1:0));assertEquals(1,db.count("SELECT COUNT(*) FROM boleto WHERE viaje_id=?",trip));}finally{pool.shutdownNow();}}
 @Test void expiredVehicleDocumentsBlockSale(){db.update("UPDATE bus SET soat_hasta=? WHERE id=(SELECT bus_id FROM viaje WHERE id=?)",LocalDate.now().minusDays(1),trip);assertThrows(BusinessException.class,()->sales.reserve(new Reserva(trip,seat)));}
 @Test void passengerValidationRejectsInvalidDni(){assertThrows(BusinessException.class,()->catalogs.save("pasajeros",null,Map.of("tipo_documento","DNI","documento","12","nombres","A","apellidos","B")));}
 @Test void passengerRegistrationCreatesAccount(){long p=catalogs.save("pasajeros",null,Map.of("tipo_documento","DNI","documento",String.valueOf(70000000+seq.incrementAndGet()),"nombres","Ana","apellidos","Prueba"));assertEquals(0,db.count("SELECT saldo FROM cuenta_fidelizacion WHERE pasajero_id=?",p));}
 @Test void percentageAboveOneHundredRejected(){assertThrows(BusinessException.class,()->catalogs.save("promociones",null,Map.of("nombre","Prueba","codigo","P"+trip,"tipo","PORCENTAJE","valor",101,"desde",LocalDate.now().toString(),"hasta",LocalDate.now().plusDays(2).toString(),"activo",true)));}
 @Test void catalogSqlInjectionKeyIsRejected(){assertThrows(BusinessException.class,()->catalogs.list("pasajero; DROP TABLE boleto"));}
 @Test void passwordsUseBcrypt(){String hash=db.one("SELECT clave_hash FROM usuario WHERE usuario='admin'").get("clave_hash").toString();assertNotEquals("Flores2026!",hash);assertTrue(encoder.matches("Flores2026!",hash));}
 @Test void reportTotalsReflectPersistedSales(){var t=sale(0);var r=reports.report(LocalDate.now().minusDays(1),LocalDate.now().plusDays(1));assertNotNull(r.get("resumen"));assertTrue(reports.trips().stream().anyMatch(x->SqlDao.id(x,"id")==trip&&SqlDao.id(x,"vendidos")==1));}
 @Test void csvEscapesSpreadsheetFormula(){String out=reports.csv(List.of(new LinkedHashMap<>(Map.of("valor","=HYPERLINK(\"bad\")"))));assertTrue(out.contains("'=HYPERLINK"));}
 @Test void anonymousCannotReadTickets()throws Exception{assertEquals(401,request(client(),"GET","/api/boletos",null,null).statusCode());}
 @Test void catalogMetadataIsAvailableForTheUserInterface()throws Exception{var response=request(login("admin"),"GET","/api/catalogos",null,null);assertEquals(200,response.statusCode());assertTrue(response.body().contains("pasajeros"));assertTrue(response.body().contains("fields"));}
 @Test void csrfIsRequiredOnLogin()throws Exception{assertEquals(403,request(client(),"POST","/api/login","username=admin&password=Flores2026%21",null).statusCode());}
 @Test void vendorCannotReadFinancialReports()throws Exception{var c=login("vendedor");assertEquals(403,request(c,"GET","/api/reportes?desde=2026-01-01&hasta=2030-01-01",null,null).statusCode());}
 @Test void controllerCannotSell()throws Exception{var c=login("controlador");assertEquals(403,json(c,"POST","/api/ventas","{\"viajeId\":1,\"asientoId\":1,\"pasajeroId\":1,\"token\":\"x\",\"promocion\":null,\"puntos\":0,\"metodo\":\"EFECTIVO\",\"operacion\":null,\"canal\":\"WEB\",\"rechazarPago\":false}").statusCode());}
 @Test void travelerCannotAccessAnotherAccount()throws Exception{var c=login("viajero");assertEquals(403,request(c,"GET","/api/fidelizacion/"+passenger,null,null).statusCode());}
 @Test void travelerCannotAccessRawPassengerCatalog()throws Exception{assertEquals(403,request(login("viajero"),"GET","/api/catalogos/pasajeros",null,null).statusCode());}
 @Test void qrIsAnActualDecodableImage()throws Exception{var t=sale(0);var c=login("admin");var bytes=c.send(HttpRequest.newBuilder(URI.create(base()+"/api/boletos/"+t.id()+"/qr")).GET().build(),HttpResponse.BodyHandlers.ofByteArray());assertEquals(200,bytes.statusCode());var img=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes.body()));var bitmap=new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(new com.google.zxing.client.j2se.BufferedImageLuminanceSource(img)));assertEquals(t.qr(),new com.google.zxing.MultiFormatReader().decode(bitmap).getText());}
 @Test void lockoutAfterFiveBadAttempts()throws Exception{String name="lock"+trip;db.update("INSERT INTO usuario(usuario,clave_hash,rol,empleado_id) VALUES(?,?,'VENDEDOR',1)",name,encoder.encode("Flores2026!"));var c=client();for(int i=0;i<5;i++){String token=token(c);request(c,"POST","/api/login","username="+name+"&password=incorrecta",token);}assertNotNull(db.one("SELECT bloqueado_hasta FROM usuario WHERE usuario=?",name).get("bloqueado_hasta"));assertEquals(401,request(c,"POST","/api/login","username="+name+"&password=Flores2026%21",token(c)).statusCode());}
 @Test void deactivationRevokesAnExistingSession()throws Exception{String name="active"+trip;db.update("INSERT INTO usuario(usuario,clave_hash,rol,empleado_id) VALUES(?,?,'VENDEDOR',1)",name,encoder.encode("Flores2026!"));var c=login(name);db.update("UPDATE usuario SET activo=FALSE WHERE usuario=?",name);assertEquals(401,request(c,"GET","/api/me",null,null).statusCode());}
 String base(){return "http://127.0.0.1:"+port;}
 HttpClient client(){return HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();}
 String token(HttpClient c)throws Exception{var r=request(c,"GET","/api/csrf",null,null);var m=java.util.regex.Pattern.compile("\"token\"\\s*:\\s*\"([^\"]+)\"").matcher(r.body());assertTrue(m.find(),r.body());return m.group(1);}
 HttpClient login(String name)throws Exception{var c=client();var r=request(c,"POST","/api/login","username="+name+"&password=Flores2026%21",token(c));assertEquals(200,r.statusCode(),r.body());return c;}
 HttpResponse<String> request(HttpClient c,String method,String path,String body,String token)throws Exception{var b=HttpRequest.newBuilder(URI.create(base()+path));if(token!=null)b.header("X-CSRF-TOKEN",token);if(body!=null)b.header("Content-Type","application/x-www-form-urlencoded");b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body));return c.send(b.build(),HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));}
 HttpResponse<String> json(HttpClient c,String method,String path,String body)throws Exception{return c.send(HttpRequest.newBuilder(URI.create(base()+path)).header("X-CSRF-TOKEN",token(c)).header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
}
